function bindFaqAccordions() {
  document.querySelectorAll(".faq-list").forEach(function(group,index) {
    group.querySelectorAll("details.faq-item").forEach(function(item) {
      item.setAttribute("name","sael-faq-"+index);
    });
    if (group.dataset.exclusiveBound) return;
    group.dataset.exclusiveBound = "true";
    // Synchronous fallback for browsers without native exclusive details groups.
    group.addEventListener("click",function(event) {
      const summary = event.target.closest?.("summary");
      const current = summary?.parentElement;
      if (!current || !current.classList.contains("faq-item") || current.open) return;
      group.querySelectorAll("details.faq-item[open]").forEach(function(item) {
        if (item !== current) item.open = false;
      });
    });
  });
}
function renderPrice() {
  const target = document.getElementById("price-body");
  if (!target) return;
  const filter = document.getElementById("price-filter");
  const search = document.getElementById("price-search");
  const chosen = filter ? filter.value : "";
  const hasCategory = priceCatalogCategories.includes(chosen);
  const results = document.getElementById("price-results");
  const prompt = document.getElementById("price-prompt");
  if (results) results.hidden = !hasCategory;
  if (prompt) prompt.hidden = hasCategory;
  if (search) search.disabled = !hasCategory;
  if (!hasCategory) {
    target.innerHTML = "";
    return;
  }
  const needle = search ? search.value.trim().toLowerCase() : "";
  const escapeHTML = function(value) {
    return String(value).replace(/[&<>"']/g,function(char){return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[char];});
  };
  const list = priceEntries.filter(function(item) {
    const searchText = [item.title[locale],priceDetail(item),item.detail,item.code,priceAmount(item),categories[locale][item.category]].join(" ").toLowerCase();
    return item.category === chosen && (!needle || searchText.includes(needle));
  });
  const methodLabel = escapeHTML(t("price.th3"));
  const priceLabel = escapeHTML(t("price.th4"));
  const quoteLabel = t("price.request");
  target.innerHTML = list.length ? list.map(function(item) {
    const title = item.title[locale];
    const code = item.code ? '<small class="price-code">'+escapeHTML(t("price.code"))+': '+escapeHTML(item.code)+'</small>' : '';
    return '<tr role="row">' +
      '<td role="cell">'+escapeHTML(categories[locale][item.category])+'</td>' +
      '<td role="cell"><strong>'+escapeHTML(title)+'</strong>'+code+'</td>' +
      '<td role="cell"><span class="price-mobile-label" aria-hidden="true">'+methodLabel+'</span>'+escapeHTML(priceDetail(item))+'</td>' +
      '<td role="cell" class="price-amount"><span class="price-mobile-label" aria-hidden="true">'+priceLabel+'</span>'+escapeHTML(priceAmount(item))+'</td>' +
      '<td role="cell"><a class="table-request" href="#request" aria-label="'+escapeHTML(quoteLabel+": "+title)+'">'+escapeHTML(quoteLabel)+'</a></td>' +
      '</tr>';
  }).join("") : '<tr role="row"><td role="cell" colspan="5">'+escapeHTML(t("price.empty"))+'</td></tr>';
}
