function applyLocale(next) {
  locale = copy[next] ? next : "ru";
  localStorage.setItem("sael-locale",locale);
  document.documentElement.lang = locale === "kg" ? "ky" : locale;
  document.querySelectorAll("[data-i18n]").forEach(function(el){const value=t(el.dataset.i18n);if(value)el.innerHTML=value;});
  document.querySelectorAll("[data-i18n-placeholder]").forEach(function(el){el.placeholder=t(el.dataset.i18nPlaceholder);});
  document.querySelectorAll("[data-i18n-aria]").forEach(function(el){el.setAttribute("aria-label",t(el.dataset.i18nAria));});
  document.querySelectorAll("[data-i18n-alt]").forEach(function(el){el.alt=t(el.dataset.i18nAlt);});
  document.querySelectorAll("[data-lang]").forEach(function(btn){const active=btn.dataset.lang===locale;btn.classList.toggle("is-active",active);btn.setAttribute("aria-pressed",active?"true":"false");});
  document.title = {ru:"SAEL — независимая аналитическая лаборатория",kg:"SAEL — көз карандысыз аналитикалык лаборатория",en:"SAEL — independent analytical laboratory"}[locale];
  document.querySelector('meta[name="description"]').content = {
    ru:"Независимая аналитическая лаборатория SAEL. Геохимические, металлургические, экологические и инспекционные исследования в Кыргызстане.",
    kg:"SAEL көз карандысыз аналитикалык лабораториясы. Кыргызстанда геохимиялык, металлургиялык, экологиялык жана инспекциялык изилдөөлөр.",
    en:"SAEL independent analytical laboratory. Geochemical, metallurgical, environmental and inspection services in Kyrgyzstan."
  }[locale];
  renderServices(); renderProcess(); renderClientSteps(); renderFaq(); renderPrice(); renderSearchResults(); renderDetail(); renderAbout();
  document.querySelector('meta[property="og:title"]')?.setAttribute("content",document.title);
  document.querySelector('meta[property="og:description"]')?.setAttribute("content",document.querySelector('meta[name="description"]')?.content || "");
  window.saelCmsRender?.(locale);
  bindFaqAccordions();
  document.querySelectorAll("#price-filter option[data-category]").forEach(function(opt){opt.textContent=categories[locale][opt.dataset.category];});
}

async function initializeSite() {
await (window.saelCmsReady || Promise.resolve());
window.saelCmsApply?.({copy,services,servicePhotos,priceEntries,categories,processSteps,clientSteps,faqs});
for (const lang of ["ru","kg","en"]) for (const key of Object.keys(servicePageUi[lang])) {
  if (copy[lang]["serviceUi."+key] !== undefined) servicePageUi[lang][key]=copy[lang]["serviceUi."+key];
}
priceCatalogCount=priceEntries.length;
priceCatalogCategories=Object.keys(categories.ru).filter(category=>priceEntries.some(item=>item.category===category));
document.querySelectorAll("[data-lang]").forEach(function(btn){btn.addEventListener("click",function(){applyLocale(btn.dataset.lang);});});
const year = document.getElementById("year"); if (year) year.textContent = new Date().getFullYear();
const menuToggle = document.querySelector(".menu-toggle");
const mainNav = document.getElementById("main-nav");
function setMenuOpen(open,restoreFocus) {
  if (!menuToggle || !mainNav) return;
  const headerBottom = document.querySelector(".site-header").getBoundingClientRect().bottom;
  mainNav.style.setProperty("--mobile-menu-top",headerBottom+"px");
  menuToggle.setAttribute("aria-expanded",String(open));
  menuToggle.setAttribute("aria-label",t(open?"menu.close":"menu.open"));
  mainNav.classList.toggle("is-open",open);
  document.body.classList.toggle("menu-open",open);
  const main = document.querySelector("main");
  const footer = document.querySelector("footer");
  if (main) main.inert = open;
  if (footer) footer.inert = open;
  if (open) mainNav.querySelector("a")?.focus();
  else if (restoreFocus) menuToggle.focus();
}
menuToggle?.addEventListener("click",function(){
  const open = menuToggle.getAttribute("aria-expanded") !== "true";
  setMenuOpen(open,false);
});
window.saelCmsSetMenuOpen=setMenuOpen;
mainNav?.querySelectorAll("a").forEach(function(a){a.addEventListener("click",function(){setMenuOpen(false,false);});});
document.addEventListener("keydown",function(event) {
  if (event.key==="Escape" && mainNav?.classList.contains("is-open")) setMenuOpen(false,true);
});
window.addEventListener("resize",function() {
  if (mainNav?.classList.contains("is-open")) setMenuOpen(window.innerWidth<=900,false);
});

const filterSelect = document.getElementById("price-filter");
if (filterSelect) {
  priceCatalogCategories.forEach(function(cat) {
    const option = document.createElement("option");
    option.value = cat; option.dataset.category = cat; option.textContent = categories[locale][cat];
    filterSelect.appendChild(option);
  });
  const requestedCategory = new URLSearchParams(location.search).get("category");
  if (priceCatalogCategories.includes(requestedCategory)) filterSelect.value = requestedCategory;
  filterSelect.addEventListener("change",function() {
    const search = document.getElementById("price-search");
    if (search) search.value = "";
    renderPrice();
  });
}
document.getElementById("price-search")?.addEventListener("input",renderPrice);
const searchDialog = document.getElementById("search-dialog");
document.querySelector(".search-open")?.addEventListener("click",function(){searchDialog.showModal();setTimeout(function(){document.getElementById("site-search")?.focus();},30);});
document.getElementById("site-search")?.addEventListener("input",renderSearchResults);
searchDialog?.addEventListener("click",function(e){if(e.target===searchDialog)searchDialog.close();});

const videoDialog = document.getElementById("sael-video-dialog");
const videoHost = document.getElementById("sael-video-host");
const videoShell = document.getElementById("sael-video-shell");
function openSaelVideo() {
  if (!videoDialog || !videoHost || videoDialog.open) return;
  const frame = document.createElement("iframe");
  frame.src = "https://www.youtube-nocookie.com/embed/teQ6Iv6p5Ms?autoplay=1&rel=0";
  frame.title = t("media.title");
  frame.allow = "autoplay; encrypted-media; fullscreen; picture-in-picture";
  frame.allowFullscreen = true;
  frame.referrerPolicy = "strict-origin-when-cross-origin";
  videoHost.replaceChildren(frame);
  videoDialog.showModal();
  document.body.classList.add("video-open");
  // Keep playback usable in a viewport-sized dialog when native fullscreen is unavailable.
  if (videoShell?.requestFullscreen) {
    try { Promise.resolve(videoShell.requestFullscreen()).catch(function(){}); } catch {}
  }
}
function stopSaelVideo() {
  videoHost?.replaceChildren();
  document.body.classList.remove("video-open");
  if (document.fullscreenElement && videoShell?.contains(document.fullscreenElement) && document.exitFullscreen) {
    Promise.resolve(document.exitFullscreen()).catch(function(){});
  }
}
document.querySelector(".hero-video-open")?.addEventListener("click",openSaelVideo);
document.querySelector(".video-dialog-close")?.addEventListener("click",function(){videoDialog?.close();});
videoDialog?.addEventListener("close",stopSaelVideo);
videoDialog?.addEventListener("click",function(event){if(event.target===videoDialog)videoDialog.close();});

const fileInput = document.querySelector('input[type="file"][name="technical_assignment"]');
const allowedFileTypes = {
  pdf:["application/pdf"],
  xls:["application/vnd.ms-excel"],
  xlsx:["application/vnd.openxmlformats-officedocument.spreadsheetml.sheet","application/zip","application/x-zip-compressed"],
  doc:["application/msword"],
  docx:["application/vnd.openxmlformats-officedocument.wordprocessingml.document","application/zip","application/x-zip-compressed"],
  zip:["application/zip","application/x-zip-compressed"]
};
function attachmentError() {
  const file = fileInput && fileInput.files ? fileInput.files[0] : null;
  if (!file) return "";
  const extension = file.name.split(".").pop().toLowerCase();
  if (!Object.prototype.hasOwnProperty.call(allowedFileTypes,extension)) return t("form.fileTypeError");
  if (file.size > 10 * 1024 * 1024) return t("form.fileSizeError");
  if (file.type && file.type!=="application/octet-stream" && !allowedFileTypes[extension].includes(file.type)) return t("form.fileTypeError");
  return "";
}
fileInput?.addEventListener("change",function(){
  const status = document.getElementById("form-status");
  const error = attachmentError();
  if (error) { status.textContent=error;status.classList.add("is-visible"); }
  else { status.textContent="";status.classList.remove("is-visible"); }
});
document.getElementById("request-form")?.addEventListener("submit",function(e){
  e.preventDefault();
  const status = document.getElementById("form-status");
  const error = attachmentError();
  if (error) { status.textContent=error;status.classList.add("is-visible");return; }
  const form = e.currentTarget;
  const submitButton = form.querySelector('button[type="submit"]');
  if (location.protocol === "file:") {
    status.textContent = t("form.status");
    status.classList.add("is-visible");
    status.scrollIntoView({behavior:"smooth",block:"nearest"});
    return;
  }
  status.textContent = t("form.sending");
  status.classList.add("is-visible");
  if (submitButton) submitButton.disabled = true;
  fetch(form.action, {method:"POST",body:new FormData(form),headers:{Accept:"application/json"}})
    .then(function(response) {
      if (response.ok) {
        status.textContent = t("form.success");
        form.reset();
      } else if ([404,405,501,503].includes(response.status)) {
        status.textContent = t("form.endpointMissing");
      } else {
        status.textContent = t("form.sendError");
      }
      status.scrollIntoView({behavior:"smooth",block:"nearest"});
    })
    .catch(function() {
      status.textContent = t("form.endpointMissing");
      status.scrollIntoView({behavior:"smooth",block:"nearest"});
    })
    .finally(function(){if(submitButton)submitButton.disabled=false;});
});
applyLocale(locale);
const requestedService = services.find(function(service) {
  return service.id === new URLSearchParams(location.search).get("service");
});
const researchField = document.querySelector('#request-form textarea[name="research"]');
if (requestedService && researchField && !researchField.value) researchField.value = requestedService.name[locale];
}
initializeSite().catch(function(error){console.error("Site initialization failed",error);});
